mapper.select:
SELECT m.* FROM agri_prod_input_ledger m
WHERE m.deleted = 0 AND m.tenant_id = #{tenantId}

    AND m.material_name LIKE CONCAT('%', #{dto.materialName}, '%')


    AND m.material_type = #{dto.materialType}


    AND m.supplier_name LIKE CONCAT('%', #{dto.supplierName}, '%')


    AND m.batch_number = #{dto.batchNumber}


    AND m.status = #{dto.status}

ORDER BY m.create_time DESC
